def count_paths(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # dp[r][c] = number of paths from (0,0) to (r,c) with sum % 3 == 0
    # We need to track counts for each remainder modulo 3
    dp = [[[0, 0, 0] for _ in range(cols)] for _ in range(rows)]

    # Base case: starting cell
    start_val = grid[0][0] % 3
    dp[0][0][start_val] = 1

    # Fill DP table
    for r in range(rows):
        for c in range(cols):
            if r == 0 and c == 0:
                continue

            # From top
            if r > 0:
                for rem in range(3):
                    dp[r][c][rem] += dp[r-1][c][(rem - grid[r][c] % 3) % 3]

            # From left
            if c > 0:
                for rem in range(3):
                    dp[r][c][rem] += dp[r][c-1][(rem - grid[r][c] % 3) % 3]

    return dp[rows-1][cols-1][0]
```

