def count_paths(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # dp[i][j] = number of paths from (0,0) to (i,j) with sum divisible by 4
    dp = [[0] * cols for _ in range(rows)]

    # Base case: starting cell
    start_val = grid[0][0]
    if start_val % 4 == 0:
        dp[0][0] = 1

    # Fill first row
    for j in range(1, cols):
        val = grid[0][j]
        if dp[0][j-1] > 0 and (dp[0][j-1] + val) % 4 == 0:
            dp[0][j] = dp[0][j-1]

    # Fill first column
    for i in range(1, rows):
        val = grid[i][0]
        if dp[i-1][0] > 0 and (dp[i-1][0] + val) % 4 == 0:
            dp[i][0] = dp[i-1][0]

    # Fill the rest
    for i in range(1, rows):
        for j in range(1, cols):
            from_top = dp[i-1][j]
            from_left = dp[i][j-1]

            current_val = grid[i][j]
            total_from_top = (from_top + current_val) % 4
            total_from_left = (from_left + current_val) % 4

            if total_from_top == 0:
                dp[i][j] = from_top
            if total_from_left == 0:
                dp[i][j] += from_left

    return dp[rows-1][cols-1]
